'use strict';
(()=>{let pending=null;
function requiresAccount(url){const host=url.hostname.toLowerCase().replace(/^www\./,'');let path=url.pathname.toLowerCase();try{path=decodeURIComponent(path)}catch{};return host==='github.com'&&/^\/[\w.-]+\/[\w.-]+\/fork\/?$/.test(path)||host==='huggingface.co'&&path.startsWith('/spaces/')&&url.searchParams.get('duplicate')==='true'}
function protect(anchor){const raw=anchor.getAttribute('href');if(!raw)return;let url;try{url=new URL(raw,location.href)}catch{return}if(!['http:','https:'].includes(url.protocol))return;if(url.origin===location.origin&&url.pathname!=='/api/open')return;let target=url;if(url.origin===location.origin){try{target=new URL(url.searchParams.get('url'))}catch{return}}if(!['http:','https:'].includes(target.protocol)||target.username||target.password)return;const gated=requiresAccount(target)&&anchor.dataset.publicDemo!=='true';if(gated)anchor.dataset.requiresLogin='true';else delete anchor.dataset.requiresLogin;if(url.origin!==location.origin&&gated)anchor.setAttribute('href','/api/open?url='+encodeURIComponent(url.href));anchor.target='_blank';anchor.rel='noopener noreferrer';}
function scan(node){if(node.nodeType!==1)return;if(node.matches('a[href]'))protect(node);node.querySelectorAll('a[href]').forEach(protect)}
function loginTarget(){if(!pending)return;const button=document.querySelector('#account-auth a[href^="/api/auth?action=start"]');if(button){const target='/api/auth?action=start&return='+encodeURIComponent(pending);if(button.getAttribute('href')!==target)button.setAttribute('href',target)}}
scan(document.documentElement);new MutationObserver(records=>{for(const record of records){if(record.type==='attributes')protect(record.target);else record.addedNodes.forEach(scan)}loginTarget()}).observe(document.documentElement,{subtree:true,childList:true,attributes:true,attributeFilter:['href']});
function activate(event){if(event.type==='auxclick'&&event.button!==1)return;const anchor=event.target.closest?.('a[href]');if(!anchor)return;protect(anchor);const url=new URL(anchor.href),protectedURL=url.origin===location.origin&&url.pathname==='/api/open';if(anchor.dataset.requiresLogin==='true'&&window.RepoAccount?.user&&!window.RepoAccount.user.githubConnected){event.preventDefault();event.stopImmediatePropagation();location.href='/api/auth?action=link-github&return='+encodeURIComponent(url.pathname+url.search);return}if(anchor.dataset.requiresLogin==='true'&&!window.RepoAccount?.user?.githubConnected&&typeof window.openAccount==='function'){event.preventDefault();event.stopImmediatePropagation();pending=url.pathname+url.search;window.openAccount();loginTarget();return}
 // Open external destinations directly from the gesture in standalone mode, avoiding
 // a same-origin redirect that mobile browsers can capture into the app window.
 if((navigator.standalone===true||window.matchMedia('(display-mode: standalone)').matches)&&!window.RepoAccount?.legal?.required){let target=protectedURL?url.searchParams.get('url'):url.origin!==location.origin?url.href:null;if(!target)return;try{const external=new URL(target);if(!['http:','https:'].includes(external.protocol)||external.username||external.password)return;event.preventDefault();window.open(external.href,'_blank','noopener,noreferrer')}catch{}}
}
document.addEventListener('click',activate,true);document.addEventListener('auxclick',activate,true);document.addEventListener('contextmenu',event=>{const anchor=event.target.closest?.('a[href]');if(anchor)protect(anchor)},true);
})();
